##=====================================================================
## Build script for TimedPetriNetEditor.jl
##
## It drives the existing GNU Make build of the C++ TimedPetriNetEditor
## repository (which produces the Julia binding shared library), then writes
## deps/deps.jl with the resolved absolute path of that library.
##
## The C++ source tree is located in this order:
##   1. ENV["TPNE_CPP_DIR"]                              (explicit override)
##   2. <pkg>/deps/TimedPetriNetEditor                   (git submodule)
##   3. a sibling checkout next to this package           (local development)
##
## A build failure only affects THIS package: it never breaks MaxPlus.jl. In
## that case deps.jl still gets written (with an empty/last-known path) so the
## module loads and reports a clear error at call time.
##=====================================================================

const DEPS_DIR = @__DIR__
const PKG_DIR = normpath(joinpath(DEPS_DIR, ".."))

"""Run a shell command, logging it; return true on success (exit code 0)."""
function run_logged(cmd::Cmd; dir::AbstractString = pwd())
    @info "[TimedPetriNetEditor.jl build] running" cmd dir
    try
        run(setenv(cmd; dir = dir))
        return true
    catch err
        @warn "[TimedPetriNetEditor.jl build] command failed" cmd err
        return false
    end
end

"""Resolve the C++ TimedPetriNetEditor source directory, or `nothing`."""
function resolve_cpp_dir()
    if haskey(ENV, "TPNE_CPP_DIR")
        d = abspath(ENV["TPNE_CPP_DIR"])
        isdir(d) && return d
        @warn "TPNE_CPP_DIR is set but not a directory" dir = d
    end
    submodule = joinpath(DEPS_DIR, "TimedPetriNetEditor")
    isdir(joinpath(submodule, "src")) && return abspath(submodule)
    # Sibling checkout: <parent of package>/TimedPetriNetEditor
    sibling = normpath(joinpath(PKG_DIR, "..", "TimedPetriNetEditor"))
    isdir(joinpath(sibling, "src")) && return abspath(sibling)
    return nothing
end

"""Search `root` for the produced Julia binding shared library, newest first."""
function find_native_lib(root::AbstractString)
    ext = Sys.isapple() ? ".dylib" : (Sys.iswindows() ? ".dll" : ".so")
    # Accept libTimedPetriJulia.so / libtimedpetrinetjulia.so and similar.
    rx = r"lib.*(timedpetri).*(julia)?.*"i
    candidates = String[]
    for (dirpath, _dirs, files) in walkdir(root; onerror = (_)->nothing)
        for f in files
            if endswith(f, ext) && occursin("timedpetri", lowercase(f)) &&
               (occursin("julia", lowercase(f)) || occursin("petrijulia", lowercase(f)))
                push!(candidates, joinpath(dirpath, f))
            end
        end
    end
    # Fall back to any lib*timedpetri*julia*.<ext> match if the strict one failed.
    if isempty(candidates)
        for (dirpath, _dirs, files) in walkdir(root; onerror = (_)->nothing)
            for f in files
                endswith(f, ext) && occursin(rx, f) && push!(candidates, joinpath(dirpath, f))
            end
        end
    end
    isempty(candidates) && return nothing
    return sort(candidates; by = f -> mtime(f), rev = true)[1]
end

function write_deps(libpath::AbstractString)
    open(joinpath(DEPS_DIR, "deps.jl"), "w") do io
        println(io, "# Auto-generated by deps/build.jl. Do not edit.")
        println(io, "const libtpne = ", repr(libpath))
        println(io)
        println(io, "function check_deps()")
        println(io, "    if isempty(libtpne) || !isfile(libtpne)")
        println(io, "        error(\"TimedPetriNetEditor native library not found at \\\"\$(libtpne)\\\". \" *")
        println(io, "              \"Re-run `import Pkg; Pkg.build(\\\"TimedPetriNetEditor\\\")`.\")")
        println(io, "    end")
        println(io, "    return nothing")
        println(io, "end")
    end
    @info "[TimedPetriNetEditor.jl build] wrote deps.jl" libpath
end

function build()
    cpp = resolve_cpp_dir()
    if cpp === nothing
        @warn """Could not locate the C++ TimedPetriNetEditor sources.
                 Set ENV["TPNE_CPP_DIR"], add it as the git submodule \
                 deps/TimedPetriNetEditor, or place a checkout next to this \
                 package. Writing an empty deps.jl."""
        write_deps("")
        return
    end
    @info "[TimedPetriNetEditor.jl build] using C++ sources" cpp

    # 1. Make sure submodules (MyMakefile .makefile, external libs) are present.
    if isdir(joinpath(cpp, ".git")) || isfile(joinpath(cpp, ".git"))
        run_logged(`git submodule update --init --recursive`; dir = cpp)
    end

    # 2. Third-party libraries, then the project (produces the Julia binding lib).
    njobs = string(max(1, Sys.CPU_THREADS))
    ok = run_logged(`make download-external-libs`; dir = cpp)
    ok &= run_logged(`make compile-external-libs`; dir = cpp)
    ok &= run_logged(`make -j$(njobs)`; dir = cpp)
    if !ok
        @warn "[TimedPetriNetEditor.jl build] C++ build reported errors; " *
              "looking for any library that may already exist."
    end

    # 3. Locate the produced shared library.
    lib = find_native_lib(cpp)
    if lib === nothing
        # Last resort: a system-wide `make install` location.
        for cand in ("/usr/local/lib/libtimedpetrinetjulia.so",
                     "/usr/local/lib/libTimedPetriJulia.so")
            isfile(cand) && (lib = cand; break)
        end
    end

    if lib === nothing
        @warn """Build finished but no Julia binding library was found under \
                 "$cpp". The package will load but native calls will error. \
                 Check the C++ build prerequisites (g++, make, git, zeromq, \
                 OpenGL/glfw/glew)."""
        write_deps("")
    else
        write_deps(lib)
    end
end

build()
